import{_ as e,c as i,o as a,a2 as o}from"./chunks/framework.Cqt7uvsz.js";const k=JSON.parse('{"title":"深度优先搜索的本质——栈结构","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm/树相关/DFS.md","filePath":"algorithm/树相关/DFS.md","lastUpdated":1766579221000}'),d={name:"algorithm/树相关/DFS.md"};function c(n,s,l,p,t,r){return a(),i("div",null,s[0]||(s[0]=[o(`<h1 id="深度优先搜索的本质——栈结构" tabindex="-1">深度优先搜索的本质——栈结构 <a class="header-anchor" href="#深度优先搜索的本质——栈结构" aria-label="Permalink to &quot;深度优先搜索的本质——栈结构&quot;">​</a></h1><p>那么如何使用编码来实现深度优先搜索呢？我们继续讨论迷宫问题，这里我给大家一个抽象过后的简单迷宫结构：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2020/4/18/1718dd0887578d3d~tplv-t2oaga2asx-jj-mark:3326:0:0:0:q75.awebp" alt="img"></p><p>图中蓝色的是入口，灰色的是岔路口，黑色的是死胡同，绿色的是出口。</p><p>基于眼前的这个迷宫结构，我们来一步一步模拟一下深度优先搜索的具体过程：</p><ol><li>从 <code>A</code> 出发，沿着唯一的一条道路往下走，遇到了第1个岔路口<code>B</code>。眼前有三个选择：<code>C</code>、<code>D</code>、<code>E</code>。这里我按照从上到下的顺序来走（你也可以按照其它顺序），先走<code>C</code>。</li><li>发现 <code>C</code>是死胡同，后退到最近的岔路口 <code>B</code>，尝试往<code>D</code>方向走。</li><li>发现<code>D</code> 是死胡同，，后退到最近的岔路口 <code>B</code>，尝试往<code>E</code>方向走。</li><li><code>E</code> 是一个岔路口，眼前有两个选择：<code>F</code> 和 <code>G</code>。按照从上到下的顺序来走，先走<code>F</code>。</li><li>发现<code>F</code> 是死胡同，后退到最近的岔路口 <code>E</code>，尝试往<code>G</code>方向走。</li><li><code>G</code> 是一个岔路口，眼前有两个选择：<code>H</code> 和 <code>I</code>。按照从上到下的顺序来走，先走<code>H</code>。</li><li>发现 <code>H</code> 是死胡同，后退到最近的岔路口 <code>G</code>，尝试往<code>I</code>方向走。</li><li><code>I</code> 就是出口，成功走出迷宫。</li></ol><p>大家观察一下这个过程，会不会觉得这些前进、后退的操作，其实和栈结构的入栈、出栈过程非常相似呢？ 现在我们把迷宫中的每一个坐标看做是栈里的一个元素，用栈来模拟这个过程：</p><ol><li>从 <code>A</code> 出发（<code>A</code>入栈），经过了<code>B</code>（<code>B</code>入栈），接下来面临 <code>C</code>、<code>D</code>、<code>E</code>三条路。这里按照从上到下的顺序来走（你也可以选择其它顺序），先走<code>C</code>（<code>C</code>入栈）。</li><li>发现 <code>C</code>是死胡同，后退到最近的岔路口 <code>B</code>（<code>C</code>出栈），尝试往<code>D</code>方向走（<code>D</code>入栈）。</li><li>发现<code>D</code> 是死胡同，，后退到最近的岔路口 <code>B</code>（<code>D</code>出栈），尝试往<code>E</code>方向走（<code>E</code>入栈）。</li><li><code>E</code> 是一个岔路口，眼前有两个选择：<code>F</code> 和 <code>G</code>。按照从上到下的顺序来走，先走<code>F</code>（<code>F</code>入栈）。</li><li>发现<code>F</code> 是死胡同，后退到最近的岔路口 <code>E</code>（<code>F</code>出栈），尝试往<code>G</code>方向走（<code>G</code>入栈）。</li><li><code>G</code> 是一个岔路口，眼前有两个选择：<code>H</code> 和 <code>I</code>。按照从上到下的顺序来走，先走<code>H</code>（<code>H</code>入栈）。</li><li>发现 <code>H</code> 是死胡同，后退到最近的岔路口 <code>G</code>（<code>H</code>出栈），尝试往<code>I</code>方向走（<code>I</code>入栈）。</li><li><code>I</code> 就是出口，成功走出迷宫。</li></ol><p>此时栈里面的内容就是<code>A</code>、<code>B</code>、<code>E</code>、<code>G</code>、<code>I</code>，因此 <code>A</code>-&gt;<code>B</code>-&gt;<code>E</code>-&gt;<code>G</code>-&gt;<code>I</code> 就是走出迷宫的路径。通过深度优先搜索，我们不仅可以定位到迷宫的出口，还可以记录下相关的路径信息。</p><p>现在大家知道了深度优先搜索的过程可以转化为一系列的入栈、出栈操作。那么深度优先搜索在编码上一般会如何实现呢？这里，就需要大家回忆一下第 5 节的内容了——DFS 中，我们往往使用<strong>递归</strong>来模拟入栈、出栈的逻辑。</p><h2 id="dfs-与二叉树的遍历" tabindex="-1">DFS 与二叉树的遍历 <a class="header-anchor" href="#dfs-与二叉树的遍历" aria-label="Permalink to &quot;DFS 与二叉树的遍历&quot;">​</a></h2><p>现在我们站在深度优先搜索的角度，重新理解一下二叉树的先序遍历过程： <img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2020/4/6/1714ec42acc57e04~tplv-t2oaga2asx-jj-mark:3326:0:0:0:q75.awebp" alt="img"></p><p>从 <code>A</code> 结点出发，访问左侧的子结点；如果左子树同样存在左侧子结点，就<strong>头也不回地继续访问下去</strong>。一直到左侧子结点为空时，才<strong>退回</strong>到距离最近的父结点、再尝试去访问父结点的右侧子结点——这个过程，和走迷宫是何其相似！事实上，在二叉树中，结点就好比是迷宫里的坐标，图中的每个结点在作为父结点时无疑是岔路口，而空结点就是死胡同。我们回顾一下二叉树先序遍历的编码实现：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 所有遍历函数的入参都是树的根结点对象</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> preorder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 递归边界，root 为空</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">root) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 输出当前遍历的结点值</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;当前遍历的结点值是：&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, root.val)  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 递归遍历左子树 </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    preorder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(root.left)  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 递归遍历右子树  </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    preorder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(root.right)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>在这个递归函数中，递归式用来先后遍历左子树、右子树（分别探索不同的道路），递归边界在识别到结点为空时会直接返回（撞到了南墙）。因此，我们可以认为，<strong>递归式就是我们选择道路的过程，而递归边界就是死胡同</strong>。二叉树的先序遍历正是深度优先搜索思想的递归实现。可以说深度优先搜索过程就类似于树的先序遍历、是树的先序遍历的推广。</p><p>这时候，可能有同学会有疑问：在二叉树遍历的递归实现里，完全没有栈的影子——这东西似乎和栈没有什么直接联系啊，为啥咱们还说深度优先搜索的本质是栈呢？</p><p>我们从两个角度来理解这个事情：</p><ul><li>首先，函数调用的底层，仍然是由栈来实现的。JS 会维护一个叫“函数调用栈”的东西，<code>preorder</code>每调用一次自己，相关调用的上下文就会被<code>push</code>进函数调用栈中；待函数执行完毕后，对应的上下文又会从调用栈中被<code>pop</code>出来。因此，即便二叉树的递归调用过程中，并没有出现栈这种数据结构，也依然改变不了递归的本质是栈的事实。</li><li>其次，DFS 作为一种思想，它和树的递归遍历一脉相承、却并不能完全地画上等号——DFS 的解题场景其实有很多，其中有一类会要求我们记录每一层递归式里路径的状态，此时就会强依赖栈结构（这一点会在下一节的真题实战中体现得淋漓尽致）。</li></ul>`,18)]))}const E=e(d,[["render",c]]);export{k as __pageData,E as default};
